            <p className="text-lg md:text-xl font-medium mb-5" style={{ color: COLORS.indigoBright }}>
              Full-Stack Python Developer &amp; Applied AI Specialist
            </p>
            <p
              className="max-w-xl mx-auto md:mx-0 text-base leading-relaxed mb-8"
